const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const callerId = String(claims.sub).trim();
const callerRole = String(claims.role || 'EMPLOYEE').toUpperCase().trim();

if (callerRole !== 'ADMIN') {
  return [{
    json: {
      valid: false,
      statusCode: 403,
      error: "Forbidden: Administrator access required to view Admin Dashboard."
    }
  }];
}

return [{
  json: {
    valid: true,
    callerId: callerId,
    callerRole: callerRole
  }
}];

const row = $input.first().json || {};

return [{
  json: {
    success: true,
    statusCode: 200,
    stats: {
      todayDate: row.today_date || new Date().toISOString().split('T')[0],
      totalEmployees: parseInt(row.total_employees || '0', 10),
      presentToday: parseInt(row.present_today || '0', 10),
      onTimeToday: parseInt(row.on_time_today || '0', 10),
      withinBufferToday: parseInt(row.within_buffer_today || '0', 10),
      lateToday: parseInt(row.late_today || '0', 10),
      halfDayToday: parseInt(row.half_day_today || '0', 10),
      absentToday: parseInt(row.absent_today || '0', 10),
      onLeaveToday: parseInt(row.on_leave_today || '0', 10),
      pendingLeavesCount: parseInt(row.pending_leaves_count || '0', 10),
      pendingOvertimeCount: parseInt(row.pending_overtime_count || '0', 10),
      todayPunchesFeed: Array.isArray(row.feed) ? row.feed : []
    }
  }
}];

